#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

TOTAL_STAGES=0
_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()
WRITTEN_SECRET=()
SKIPPED=()

_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

say()  { printf '  %s\n' "$1"; }
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1
  fi
  printf '%s' "$value"
}

ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {
ENV_FILE=".env.local"
TOTAL_STAGES=5

banner "Admin auth: Supabase + Google OAuth"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Supabase: create the dedicated project"
say "Create a NEW project for admin auth + catalog writes. Do not reuse the"
say "resource-request project. Free plan is the current decision."
open_url "https://supabase.com/dashboard/new"
step "Choose the organization, a project name, and the region closest to the admins (Singapore/Tokyo)."
step "Wait for provisioning, then open Project Settings → General and copy the project ref."
ask SUPABASE_PROJECT_REF "Project ref:"
if [[ -z "${SUPABASE_PROJECT_REF:-}" ]]; then
  warn "A project ref is required; re-run when you have it."
  return 1
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Google Cloud: OAuth consent + client"
say "The site uses Google OAuth only; no SMTP or sending domain is needed."
open_url "https://console.cloud.google.com/apis/credentials/consent"
step "Configure the OAuth consent screen: External; app name; support email."
step "Scopes: openid, email, profile. Add every admin's Google email as a test user while in Testing."
open_url "https://console.cloud.google.com/apis/credentials"
step "Create credentials → OAuth client ID → Web application."
step "Authorized redirect URI: https://${SUPABASE_PROJECT_REF}.supabase.co/auth/v1/callback"
step "Copy the Client ID and Client Secret; you will paste them into Supabase next."
pause "Press Enter when the OAuth client exists."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Supabase: enable Google and set URLs"
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/auth/providers"
step "Google → Enable; paste Client ID and Client Secret; Save."
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/auth/url-configuration"
step "Site URL: https://daxigua732.github.io/fnaf-fan-games-archive/"
step "Additional redirect URLs: http://localhost:5173/ and https://daxigua732.github.io/fnaf-fan-games-archive/"
step "Do NOT add a /#/admin/... URL; the OAuth callback lands on the site root."
pause "Press Enter when the provider and URLs are saved."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Supabase: API keys → local env + GitHub variables"
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/settings/api"
step "Copy the Project URL and the anon public / publishable key."
step "Never copy service_role or a secret key into the app."
VITE_SUPABASE_URL="https://${SUPABASE_PROJECT_REF}.supabase.co"
ask VITE_SUPABASE_ANON_KEY "Paste the anon/publishable key:"
if [[ -z "${VITE_SUPABASE_ANON_KEY:-}" ]]; then
  warn "The anon/publishable key is required; re-run when you have it."
  return 1
fi
write_env VITE_SUPABASE_URL "$VITE_SUPABASE_URL"
write_env VITE_SUPABASE_ANON_KEY "$VITE_SUPABASE_ANON_KEY"
set_var VITE_SUPABASE_URL "$VITE_SUPABASE_URL"
set_var VITE_SUPABASE_ANON_KEY "$VITE_SUPABASE_ANON_KEY"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Verify and record"
if command -v curl >/dev/null 2>&1; then
  code=$(curl -sS -o /dev/null -w '%{http_code}' \
    "${VITE_SUPABASE_URL}/auth/v1/health" \
    -H "apikey: ${VITE_SUPABASE_ANON_KEY}" 2>/dev/null || true)
  if [[ "$code" == "200" ]]; then
    step "Auth health check: HTTP 200."
  else
    warn "Auth health check returned HTTP ${code:-?}; verify the project URL/key and that Google is enabled."
  fi
else
  warn "curl is unavailable; verify the project manually."
fi
step "After the code lands, sign in with Google and enroll TOTP as the first owner."
note "The deploy workflow does not inject these variables yet; that code change is part of the implementation."
note "Next: apply migrations, seed the first owner, then test invite acceptance + session revocation."
pause "Press Enter to finish."

finish
}

run_wizard "$@"; exit
